import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"올바름 인력관리시스템 코딩 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"coding-guide.md","filePath":"coding-guide.md"}'),l={name:"coding-guide.md"};function o(c,e,r,s,n,u){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="올바름-인력관리시스템-코딩-가이드" tabindex="-1">올바름 인력관리시스템 코딩 가이드 <a class="header-anchor" href="#올바름-인력관리시스템-코딩-가이드" aria-label="Permalink to &quot;올바름 인력관리시스템 코딩 가이드&quot;">​</a></h1><h2 id="_1-기본-기준" tabindex="-1">1. 기본 기준 <a class="header-anchor" href="#_1-기본-기준" aria-label="Permalink to &quot;1. 기본 기준&quot;">​</a></h2><ul><li>TypeScript <code>strict</code> 모드를 유지한다.</li><li>Next.js App Router와 React 함수형 컴포넌트를 사용한다.</li><li>내부 모듈은 <code>@/</code> 경로 별칭을 사용한다.</li><li>코드·파일명은 영문, 사용자 화면 문구는 자연스러운 한국어를 사용한다.</li><li>업무 규칙은 화면 컴포넌트가 아니라 <code>src/lib</code>에 배치한다.</li></ul><h2 id="_2-디렉터리-규칙" tabindex="-1">2. 디렉터리 규칙 <a class="header-anchor" href="#_2-디렉터리-규칙" aria-label="Permalink to &quot;2. 디렉터리 규칙&quot;">​</a></h2><table tabindex="0"><thead><tr><th>위치</th><th>용도</th></tr></thead><tbody><tr><td><code>src/app</code></td><td>페이지, 레이아웃, Route Handler</td></tr><tr><td><code>src/components</code></td><td>여러 화면에서 재사용하는 UI</td></tr><tr><td><code>src/lib</code></td><td>도메인 로직, 데이터 접근, 외부 연동</td></tr><tr><td><code>public</code></td><td>이미지, 아이콘, 폰트 등 정적 자산</td></tr><tr><td><code>supabase/migrations</code></td><td>DB 변경 SQL</td></tr><tr><td><code>supabase/functions</code></td><td>Supabase Edge Function</td></tr><tr><td><code>docs</code></td><td>요구·설계·운영 문서</td></tr></tbody></table><h2 id="_3-명명-규칙" tabindex="-1">3. 명명 규칙 <a class="header-anchor" href="#_3-명명-규칙" aria-label="Permalink to &quot;3. 명명 규칙&quot;">​</a></h2><ul><li>컴포넌트와 타입은 PascalCase, 함수와 변수는 camelCase를 사용한다.</li><li>파일과 URL 세그먼트는 소문자 kebab-case를 기본으로 한다.</li><li>DB 테이블·컬럼은 snake_case를 사용한다.</li><li>Boolean 값은 <code>is</code>, <code>has</code>, <code>can</code> 등 의미가 드러나는 접두사를 사용한다.</li></ul><h2 id="_4-typescript와-react" tabindex="-1">4. TypeScript와 React <a class="header-anchor" href="#_4-typescript와-react" aria-label="Permalink to &quot;4. TypeScript와 React&quot;">​</a></h2><ul><li><code>any</code> 사용을 피하고 API 입력은 <code>unknown</code>에서 검증한다.</li><li>상태는 사용하는 컴포넌트 가까이에 두고, 공유가 필요한 경우에만 상위로 이동한다.</li><li>서버에서 처리 가능한 데이터 조회는 서버 로직으로 유지한다.</li><li>브라우저 API를 사용하는 컴포넌트에만 <code>&quot;use client&quot;</code>를 지정한다.</li><li>비동기 실행 중 버튼을 비활성화하고 처리 상태를 표시한다.</li></ul><h2 id="_5-api와-오류-처리" tabindex="-1">5. API와 오류 처리 <a class="header-anchor" href="#_5-api와-오류-처리" aria-label="Permalink to &quot;5. API와 오류 처리&quot;">​</a></h2><ul><li>Route Handler는 요청 파싱, 인증·입력 검증, 서비스 호출, HTTP 응답만 담당한다.</li><li>정상 응답 키는 <code>employee</code>, <code>rows</code>, <code>reports</code>처럼 데이터 의미가 드러나게 한다.</li><li>사용자 오류와 시스템 오류를 구분하고 내부 비밀정보를 응답에 포함하지 않는다.</li><li>삭제 작업은 화면 확인 절차와 서버 검증을 모두 적용한다.</li></ul><h2 id="_6-db-접근" tabindex="-1">6. DB 접근 <a class="header-anchor" href="#_6-db-접근" aria-label="Permalink to &quot;6. DB 접근&quot;">​</a></h2><ul><li>일반 데이터 접근은 공통 Supabase 클라이언트를 사용한다.</li><li>서비스 역할이 필요한 작업은 서버 전용 관리 클라이언트만 사용한다.</li><li>DB 오류는 도메인에 맞는 사용자 메시지로 변환한다.</li><li>스키마 변경은 기존 마이그레이션 수정 대신 새 마이그레이션으로 추가한다.</li></ul><h2 id="_7-ui-작성" tabindex="-1">7. UI 작성 <a class="header-anchor" href="#_7-ui-작성" aria-label="Permalink to &quot;7. UI 작성&quot;">​</a></h2><ul><li><code>디자인 가이드.md</code>와 <code>src/app/globals.css</code>의 공통 토큰을 따른다.</li><li>버튼은 동작을 설명하는 텍스트 또는 접근성 이름을 가진 아이콘을 사용한다.</li><li>폼은 라벨, 필수값, 검증 오류, 처리 결과를 제공한다.</li><li>반응형 표와 모바일 터치 영역을 확인한다.</li></ul><h2 id="_8-테스트와-품질" tabindex="-1">8. 테스트와 품질 <a class="header-anchor" href="#_8-테스트와-품질" aria-label="Permalink to &quot;8. 테스트와 품질&quot;">​</a></h2><ul><li>기능 변경 시 정상, 입력 오류, 권한 오류, 외부 연동 실패 테스트를 추가한다.</li><li>테스트 파일은 대상 파일 가까이에 <code>*.test.ts</code> 또는 <code>*.test.tsx</code>로 둔다.</li><li>커밋 전 <code>npm run lint</code>, <code>npm test</code>, <code>npm run build</code>를 실행한다.</li><li>생성 파일과 비밀정보는 커밋 대상에서 제외한다.</li></ul><h2 id="_9-git-규칙" tabindex="-1">9. Git 규칙 <a class="header-anchor" href="#_9-git-규칙" aria-label="Permalink to &quot;9. Git 규칙&quot;">​</a></h2><ul><li>한 커밋에는 하나의 명확한 목적을 담는다.</li><li>커밋 메시지는 <code>docs:</code>, <code>feat:</code>, <code>fix:</code>, <code>test:</code> 등 변경 성격을 표시한다.</li><li>사용자 작업과 무관한 파일을 함께 수정하거나 정리하지 않는다.</li></ul>',19)])])}const _=t(l,[["render",o]]);export{p as __pageData,_ as default};
